/**
 * WP-D04 adversarial corpus for contribution-association evidence.
 *
 * Every case is synthetic: no real capture, commit, or credential appears here.
 * Expected values record what the CURRENT engine must do (association-only,
 * conservative, withhold rather than inflate) — they are not endorsements that
 * this is the only defensible answer. Categories are descriptive, not a truth
 * taxonomy. Nothing in this corpus may be cited as authorship, quality,
 * outcome, or value evidence; association-only, never authorship.
 */

import type {
  ContributionArtifact,
  ContributionCandidatesInput,
  ContributionEvidenceMethod,
  ContributionEvidenceStatus,
  ContributionOpaqueFile,
  ContributionTextFile,
  ContributionAssessmentInput,
} from '../../src/git/contribution.ts';


export const CONTRIBUTION_CORPUS_VERSION = 'wp-d04-corpus/1';

export interface ContributionCorpusCase {
  readonly id: string;
  readonly provenance: 'synthetic';
  readonly title: string;
  readonly rationale: string;
  readonly categories: readonly string[];
  readonly expected: { readonly status: ContributionEvidenceStatus; readonly method: ContributionEvidenceMethod };
  readonly input: ContributionAssessmentInput | ContributionCandidatesInput;
  readonly nonClaims: readonly string[];
  readonly limitations: readonly string[];
}

type MutableArtifact = {
  -readonly [K in keyof ContributionArtifact]: ContributionArtifact[K];
};

type MutableTextFile = {
  -readonly [K in keyof ContributionTextFile]: ContributionTextFile[K];
};

type MutableOpaqueFile = {
  -readonly [K in keyof ContributionOpaqueFile]: ContributionOpaqueFile[K];
};

type MutableFile = MutableTextFile | MutableOpaqueFile;

function textFile(path: string, addedLines: string[], extra: Partial<MutableTextFile> = {}): MutableFile {
  return { path, kind: 'text', addedLines, ...extra };
}

function opaqueFile(path: string, kind: 'generated' | 'binary' | 'unsupported'): MutableFile {
  return { path, kind };
}

function artifactOf(id: string, sourceId: string, files: MutableFile[], patchIdentity: string | null = null): MutableArtifact {
  return { id, sourceId, files, patchIdentity };
}

function assessPair(
  id: string,
  title: string,
  rationale: string,
  categories: string[],
  expected: { status: ContributionEvidenceStatus; method: ContributionEvidenceMethod },
  source: MutableArtifact,
  target: MutableArtifact,
  temporal?: ContributionAssessmentInput['temporal'],
): ContributionCorpusCase {
  return {
    id,
    provenance: 'synthetic',
    title,
    rationale,
    categories,
    expected,
    input: temporal === undefined ? { source, target } : { source, target, temporal },
    nonClaims: ['ai_authorship', 'outcome_success', 'code_quality', 'realized_value'],
    limitations: [
      'Synthetic association evidence: verifies what the current engine does, not what a better engine should do.',
      'Baseline scores are diagnostic comparisons, not ground truth, thresholds, or value evidence.',
    ],
  };
}

function candidatesCase(
  id: string,
  title: string,
  rationale: string,
  categories: string[],
  expected: { status: ContributionEvidenceStatus; method: ContributionEvidenceMethod },
  input: ContributionCandidatesInput,
): ContributionCorpusCase {
  const base = assessPair(id, title, rationale, categories, expected, artifactOf('unused', 'unused', []), artifactOf('unused', 'unused', []));
  return { ...base, input };
}

const BASE_MS = 1_700_000_000_000;

function withinWindow(): ContributionAssessmentInput['temporal'] {
  return {
    sourceObservedAtMs: BASE_MS + 1_000,
    targetObservedAtMs: BASE_MS + 5_000,
    windowStartMs: BASE_MS,
    windowEndMs: BASE_MS + 10_000,
  };
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === 'object') {
    for (const item of Object.values(value)) deepFreeze(item);
    Object.freeze(value);
  }
  return value;
}

