export const CONTRIBUTION_CORPUS_DIGEST_ALGORITHM = 'sha256';

export function corpusStats(cases: readonly ContributionCorpusCase[]): {
  readonly total: number;
  readonly byStatus: Readonly<Record<string, number>>;
  readonly byMethod: Readonly<Record<string, number>>;
} {
  const byStatus: Record<string, number> = {};
  const byMethod: Record<string, number> = {};
  for (const entry of cases) {
    byStatus[entry.expected.status] = (byStatus[entry.expected.status] ?? 0) + 1;
    byMethod[entry.expected.method] = (byMethod[entry.expected.method] ?? 0) + 1;
  }
  return { total: cases.length, byStatus, byMethod };
}
